package com.travelplan.gateway;
import java.util.UUID; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.web.server.WebFilter;
@Configuration public class RequestIdFilter { private static final Logger log=LoggerFactory.getLogger(RequestIdFilter.class); @Bean WebFilter requestId(){return (exchange,chain)->{String incoming=exchange.getRequest().getHeaders().getFirst("X-Request-ID");String id=incoming==null||incoming.isBlank()?UUID.randomUUID().toString():incoming;exchange.getResponse().getHeaders().set("X-Request-ID",id);return chain.filter(exchange).doFinally(signal->log.info("{\"timestamp\":\"{}\",\"service\":\"api-gateway\",\"severity\":\"INFO\",\"traceId\":\"{}\",\"operation\":\"{}\",\"status\":\"{}\"}",java.time.Instant.now(),id,exchange.getRequest().getMethod()+" "+exchange.getRequest().getPath(),exchange.getResponse().getStatusCode()==null?0:exchange.getResponse().getStatusCode().value())).contextWrite(ctx->ctx.put("travelPlan.requestId",id));};}}
